    with open(boot_path, "w") as f:
        json.dump(bootstrap, f, indent=2)
    print(f"  Written: {boot_path}")

    # Print bootstrap summary
    print(f"\n{'='*80}")
    print(f"  Bootstrap CIs (n={args.n_bootstrap}, seed={args.seed})")
    print(f"{'='*80}")
    for config_key, ci_data in sorted(bootstrap["configs"].items()):
        lo, hi = ci_data["ci_95"]
        regime = ci_data.get("regime", "")
        print(f"  {config_key:<50} [{regime:>6}] R@1={ci_data['point']*100:.2f}%  95%CI=[{lo*100:.2f}, {hi*100:.2f}]")

    for label_key, label_name in [("pairwise_all_seeds", "All seeds"), ("pairwise_comparable", "Comparable (s43+s44)")]:
        pairwise = bootstrap[label_key]
        if pairwise:
            print(f"\n  Pairwise comparisons -- {label_name}:")
            for pair_key, pair_data in sorted(pairwise.items()):
                if pair_data.get("mean_diff") is not None:
